namespace AnimPreview {
Mat4 Mat4::Translation(float x, float y, float z) { Mat4 t; t(0, 3) = x; t(1, 3) = y; t(2, 3) = z; return t; }

Mat4 Mat4::operator*(const Mat4& o) const {
    Mat4 r;
    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 4; ++j) {
            float sum = 0;
            for (int k = 0; k < 4; ++k) sum += (*this)(i, k) * o(k, j);
            r(i, j) = sum;
        }
    return r;
}

Mat4 Mat4::AffineInverse() const {
    const auto& a = *this;
    const float det = a(0,0) * (a(1,1) * a(2,2) - a(1,2) * a(2,1)) - a(0,1) * (a(1,0) * a(2,2) - a(1,2) * a(2,0)) + a(0,2) * (a(1,0) * a(2,1) - a(1,1) * a(2,0));
    if (std::fabs(det) < 1e-20f) throw std::runtime_error("Singular bone matrix");
    const float inv = 1.0f / det;
    Mat4 r;
    r(0,0) = (a(1,1) * a(2,2) - a(1,2) * a(2,1)) * inv;
    r(0,1) = (a(0,2) * a(2,1) - a(0,1) * a(2,2)) * inv;
    r(0,2) = (a(0,1) * a(1,2) - a(0,2) * a(1,1)) * inv;
    r(1,0) = (a(1,2) * a(2,0) - a(1,0) * a(2,2)) * inv;
    r(1,1) = (a(0,0) * a(2,2) - a(0,2) * a(2,0)) * inv;
    r(1,2) = (a(0,2) * a(1,0) - a(0,0) * a(1,2)) * inv;
    r(2,0) = (a(1,0) * a(2,1) - a(1,1) * a(2,0)) * inv;
    r(2,1) = (a(0,1) * a(2,0) - a(0,0) * a(2,1)) * inv;
    r(2,2) = (a(0,0) * a(1,1) - a(0,1) * a(1,0)) * inv;
    for (int i = 0; i < 3; ++i) r(i, 3) = -(r(i,0) * a(0,3) + r(i,1) * a(1,3) + r(i,2) * a(2,3));
    return r;
}

std::array<float, 3> Mat4::Point(const std::array<float, 3>& p) const {
    const auto& a = *this;
    return {a(0,0) * p[0] + a(0,1) * p[1] + a(0,2) * p[2] + a(0,3),
            a(1,0) * p[0] + a(1,1) * p[1] + a(1,2) * p[2] + a(1,3),
            a(2,0) * p[0] + a(2,1) * p[1] + a(2,2) * p[2] + a(2,3)};
}

std::array<float, 3> Mat4::Vector(const std::array<float, 3>& v) const {
    const auto& a = *this;
    return {a(0,0) * v[0] + a(0,1) * v[1] + a(0,2) * v[2],
            a(1,0) * v[0] + a(1,1) * v[1] + a(1,2) * v[2],
            a(2,0) * v[0] + a(2,1) * v[1] + a(2,2) * v[2]};
}

namespace {
Mat4 AxisMatrix(int axis, float angle) {
    const float c = std::cos(angle), s = std::sin(angle);
    Mat4 r;
    const int a = (axis + 1) % 3, b = (axis + 2) % 3;
    r(a, a) = c; r(a, b) = -s; r(b, a) = s; r(b, b) = c;
    return r;
}
}

Mat4 EulerMatrix(float x, float y, float z, RotationMode mode) {
    const Mat4 rx = AxisMatrix(0, x), ry = AxisMatrix(1, y), rz = AxisMatrix(2, z);
    switch (mode) {
    case RotationMode::XYZ: return rz * ry * rx;
    case RotationMode::XZY: return ry * rz * rx;
    case RotationMode::YXZ: return rz * rx * ry;
    case RotationMode::YZX: return rx * rz * ry;
    case RotationMode::ZXY: return ry * rx * rz;
    case RotationMode::ZYX: return rx * ry * rz;
    default: return {};
    }
}

namespace {
struct Reader {
    std::span<const Byte> bytes;
    size_t at = 0;
    template<class T> T Get() {
        if (at > bytes.size() || bytes.size() - at < sizeof(T)) throw std::runtime_error("Truncated preview model");
        T value; memcpy(&value, bytes.data() + at, sizeof(T)); at += sizeof(T); return value;
    }
};
}

Model Model::Load(std::span<const Byte> bytes) {
    Reader r{bytes};
    if (bytes.size() < 4 || memcmp(bytes.data(), "TKMP", 4)) throw std::runtime_error("Not a preview model");
    r.at = 4;
    const auto version = r.Get<uint32_t>(), boneCount = r.Get<uint32_t>(), skinCount = r.Get<uint32_t>(),
               vertexCount = r.Get<uint32_t>(), triangleCount = r.Get<uint32_t>(), materialCount = r.Get<uint32_t>();
    if (version != 1) throw std::runtime_error("Unsupported preview model version");
    if (boneCount > 4096 || skinCount > boneCount || vertexCount > 65536 || triangleCount > 1u << 20 || materialCount > 256)
        throw std::runtime_error("Preview model counts out of range");
    Model model;
    model.bones.resize(boneCount);
    for (auto& bone : model.bones) {
        const auto length = r.Get<uint8_t>();
        if (bytes.size() - r.at < length) throw std::runtime_error("Truncated preview model");
        bone.name.assign(reinterpret_cast<const char*>(bytes.data() + r.at), length); r.at += length;
        bone.parent = r.Get<int16_t>();
        const auto mode = r.Get<uint8_t>();
        if (mode > uint8_t(RotationMode::Quaternion)) throw std::runtime_error("Unknown bone rotation mode");
        bone.mode = RotationMode(mode);
        bone.flags = r.Get<uint8_t>();
        for (auto& value : bone.rest.m) value = r.Get<float>();
        if (bone.parent >= int(boneCount)) throw std::runtime_error("Bone parent out of range");
    }
    for (auto& bone : model.bones) {
        bone.restInverse = bone.rest.AffineInverse();
        bone.local = bone.parent < 0 ? bone.rest : model.bones[bone.parent].restInverse * bone.rest;
    }
    // Parents first (Blender lists bones depth first, but do not depend on it); a cycle is malformed data.
    std::vector<int> state(boneCount, 0);
    for (int start = 0; start < int(boneCount); ++start) {
        std::vector<int> chain;
        for (int b = start; b >= 0 && state[b] == 0; b = model.bones[b].parent) { state[b] = 1; chain.push_back(b); }
        for (auto it = chain.rbegin(); it != chain.rend(); ++it) {
            const int parent = model.bones[*it].parent;
            if (parent >= 0 && state[parent] != 2) throw std::runtime_error("Bone hierarchy has a cycle");
            state[*it] = 2; model.order.push_back(*it);
        }
    }
    model.skin.resize(skinCount);
    for (auto& s : model.skin) { s = r.Get<uint16_t>(); if (s >= boneCount) throw std::runtime_error("Skin bone out of range"); }
    model.vertices.resize(vertexCount);
    for (auto& v : model.vertices) {
        for (auto& c : v.position) c = r.Get<float>();
        for (auto& c : v.normal) c = r.Get<int8_t>() / 127.0f;
        r.Get<uint8_t>();
        for (auto& b : v.bones) { b = r.Get<uint16_t>(); if (b >= skinCount && skinCount) throw std::runtime_error("Vertex bone out of range"); }
        float total = 0;
        for (auto& w : v.weights) { w = r.Get<uint8_t>() / 255.0f; total += w; }
        if (total > 0) for (auto& w : v.weights) w /= total;
    }
    model.materials.resize(materialCount);
    for (auto& m : model.materials) {
        m.first = r.Get<uint32_t>(); m.count = r.Get<uint32_t>();
        for (auto& c : m.colour) c = r.Get<uint8_t>() / 255.0f;
        r.Get<uint8_t>();
        if (m.first > triangleCount || m.count > triangleCount - m.first) throw std::runtime_error("Material range out of range");
    }
    model.indices.resize(size_t(triangleCount) * 3);
    for (auto& i : model.indices) { i = r.Get<uint16_t>(); if (i >= vertexCount) throw std::runtime_error("Triangle index out of range"); }
    return model;
}

const Model& Model::Embedded() {
    static const Model model = Load(std::span<const Byte>(mannequin_bin, mannequin_bin_size));
    return model;
}

int Model::Find(std::string_view name) const {
    for (size_t i = 0; i < bones.size(); ++i) if (bones[i].name == name) return int(i);
    return -1;
}

namespace {
constexpr float Pi = std::numbers::pi_v<float>, HalfPi = Pi / 2;
using Row3 = std::array<std::array<double, 3>, 3>;
// BlenderTekkenDirect helpers, ported as they are (TekkenAnimHelper.py): get_quaternion_from_euler returns
// [x, y, z, w] and quaternionToRotationMatrix reads it as [w, x, y, z]. convertArmToBlenderXYZ's constants were tuned
// against that behaviour, so it is kept.
std::array<double, 4> QuaternionFromEuler(double roll, double pitch, double yaw) {
    const double cr = std::cos(roll / 2), sr = std::sin(roll / 2), cp = std::cos(pitch / 2), sp = std::sin(pitch / 2),
                 cy = std::cos(yaw / 2), sy = std::sin(yaw / 2);
    return {sr * cp * cy - cr * sp * sy, cr * sp * cy + sr * cp * sy, cr * cp * sy - sr * sp * cy, cr * cp * cy + sr * sp * sy};
}
Row3 QuaternionToMatrix(const std::array<double, 4>& q) {
    const double q0 = q[0], q1 = q[1], q2 = q[2], q3 = q[3];
    return {{{2 * (q0 * q0 + q1 * q1) - 1, 2 * (q1 * q2 - q0 * q3), 2 * (q1 * q3 + q0 * q2)},
             {2 * (q1 * q2 + q0 * q3), 2 * (q0 * q0 + q2 * q2) - 1, 2 * (q2 * q3 - q0 * q1)},
             {2 * (q1 * q3 - q0 * q2), 2 * (q2 * q3 + q0 * q1), 2 * (q0 * q0 + q3 * q3) - 1}}};
}
Row3 Multiply(const Row3& a, const Row3& b) {
    Row3 r{};
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) for (int k = 0; k < 3; ++k) r[i][j] += a[i][k] * b[k][j];
    return r;
}
Row3 Inverse(const Row3& a) {
    const double det = a[0][0] * (a[1][1] * a[2][2] - a[1][2] * a[2][1]) - a[0][1] * (a[1][0] * a[2][2] - a[1][2] * a[2][0]) + a[0][2] * (a[1][0] * a[2][1] - a[1][1] * a[2][0]);
    const double i = 1 / det;
    return {{{(a[1][1] * a[2][2] - a[1][2] * a[2][1]) * i, (a[0][2] * a[2][1] - a[0][1] * a[2][2]) * i, (a[0][1] * a[1][2] - a[0][2] * a[1][1]) * i},
             {(a[1][2] * a[2][0] - a[1][0] * a[2][2]) * i, (a[0][0] * a[2][2] - a[0][2] * a[2][0]) * i, (a[0][2] * a[1][0] - a[0][0] * a[1][2]) * i},
             {(a[1][0] * a[2][1] - a[1][1] * a[2][0]) * i, (a[0][1] * a[2][0] - a[0][0] * a[2][1]) * i, (a[0][0] * a[1][1] - a[0][1] * a[1][0]) * i}}};
}
// getRotationFromMatrix, mode 1 (YXZ).
std::array<double, 3> RotationYXZ(const Row3& te) {
    const double m11 = te[0][0], m13 = te[0][2], m21 = te[1][0], m22 = te[1][1], m23 = te[1][2], m31 = te[2][0], m33 = te[2][2];
    const double x = std::asin(-std::clamp(m23, -1.0, 1.0));
    if (std::fabs(m23) < 0.9999999) return {x, std::atan2(m13, m33), std::atan2(m21, m22)};
    return {x, std::atan2(-m31, m11), 0};
}
// convertArmToBlenderXYZ: T7 shoulder channel -> Blender Euler.
std::array<float, 3> ShoulderToBlender(double x, double y, double z) {
    static const Row3 originInverse = Inverse(QuaternionToMatrix(QuaternionFromEuler(-std::numbers::pi / 2, std::numbers::pi / 2, 0)));
    const auto r = RotationYXZ(Multiply(QuaternionToMatrix(QuaternionFromEuler(x, y, z)), originInverse));
    return {float(-r[2]), float(r[1]), float(-r[0])};
}

struct Mapping {
    int offset, base, spine1, hip, neck, head, rShoulder, rArm, rForeArm, rHand, lShoulder, lArm, lForeArm, lHand,
        rUpLeg, rLeg, rFoot, lUpLeg, lLeg, lFoot;
};
const Mapping& BoneMapping(const Model& model) {
    // One model per process (the embedded one) in practice; tests may load others, so key on the address.
    thread_local const Model* cached = nullptr;
    thread_local Mapping mapping{};
    if (cached != &model) {
        auto find = [&](const char* name) { const int i = model.Find(name); if (i < 0) throw std::runtime_error(std::string("Preview model lacks bone ") + name); return i; };
        mapping = {find("BODY_SCALE__group"), find("BASE"), find("Spine1"), find("Hip"), find("Neck"), find("Head"),
                   find("R_Shoulder"), find("R_Arm"), find("R_ForeArm"), find("R_Hand"), find("L_Shoulder"), find("L_Arm"),
                   find("L_ForeArm"), find("L_Hand"), find("R_UpLeg"), find("R_Leg"), find("R_Foot"), find("L_UpLeg"),
                   find("L_Leg"), find("L_Foot")};
        cached = &model;
    }
    return mapping;
}
}

Channels Interpolate(const Channels& a, const Channels& b, float t) {
    constexpr float TwoPi = 2 * Pi;
    Channels result;
    for (size_t i = 0; i < result.size(); ++i) {
        float delta = b[i] - a[i];
        if (i >= 9) delta = std::remainder(delta, TwoPi);
        result[i] = a[i] + delta * t;
    }
    return result;
}

std::vector<Mat4> Pose(const Model& model, const Channels& a, const PoseOptions& options) {
    const auto& m = BoneMapping(model);
    std::vector<Mat4> basis(model.bones.size());
    auto rotate = [&](int bone, float x, float y, float z) { basis[bone] = EulerMatrix(x, y, z, model.bones[bone].mode); };
    // applyRotationFromAnimdata (TekkenAnimHelper.py) for the rotations. Positions: LocalPos (channel 1) is the body
    // offset, GlobalPos (channel 0) the root motion, in millimetres. Posed this way the mannequin faces +X: the game's
    // axes (forward +Z) turn by -90 degrees about Y, x = game z and z = -game x, as getAnimFrameFromBones reads them back
    // (applyRotationFromAnimdata's own translation used other axes). Checked against the native T8 skeleton: every limb
    // of a PANM's forward kinematics matches the posed mannequin within a few degrees after this turn.
    float gameX = a[3], gameZ = a[5];
    if (options.rootMotion) { gameX += a[0]; gameZ += a[2]; }
    basis[m.offset] = Mat4::Translation(gameZ / 1000, a[4] / 1000 - 1.15f, -gameX / 1000);
    rotate(m.base, a[11], a[10], -a[9]);
    rotate(m.spine1, a[14] - HalfPi, a[13], -a[12]);
    rotate(m.hip, a[17] + HalfPi, a[16], -a[15]);
    rotate(m.neck, a[23], a[22], -a[21]);
    rotate(m.head, a[25], a[26] - HalfPi, a[24] - HalfPi);
    {
        const auto r = ShoulderToBlender(a[27], a[28], a[29]);
        rotate(m.rShoulder, r[0], r[1], r[2]);
    }
    rotate(m.rArm, -a[30] - HalfPi, -a[32], -a[31]);
    rotate(m.rForeArm, -a[33], a[34], -a[35]);
    rotate(m.rHand, a[36] - HalfPi, a[38], -a[37]);
    {
        const auto r = ShoulderToBlender(a[39], a[40], a[41]);
        rotate(m.lShoulder, -r[0], r[1], r[2] + Pi);
    }
    rotate(m.lArm, a[42] + HalfPi, -a[44], a[43]);
    rotate(m.lForeArm, a[45], a[46], a[47]);
    rotate(m.lHand, -a[48] + HalfPi, -a[50], -a[49]);
    rotate(m.rUpLeg, a[53], a[52], -a[51]);
    rotate(m.rLeg, a[56], a[55], -a[54]);
    rotate(m.rFoot, a[59], a[58], -a[57]);
    rotate(m.lUpLeg, a[62], a[61], -a[60]);
    rotate(m.lLeg, a[65], a[64], -a[63]);
    rotate(m.lFoot, a[68], a[67], -a[66]);

    std::vector<Mat4> pose(model.bones.size());
    for (int b : model.order) {
        const auto& bone = model.bones[b];
        pose[b] = (bone.parent < 0 ? bone.local : pose[bone.parent] * bone.local) * basis[b];
    }
    return pose;
}

void Skin(const Model& model, std::span<const Mat4> pose, std::vector<float>& positions, std::vector<float>& normals) {
    std::vector<Mat4> skin(model.skin.size());
    for (size_t i = 0; i < skin.size(); ++i) skin[i] = pose[model.skin[i]] * model.bones[model.skin[i]].restInverse;
    positions.resize(model.vertices.size() * 3);
    normals.resize(model.vertices.size() * 3);
    for (size_t v = 0; v < model.vertices.size(); ++v) {
        const auto& vertex = model.vertices[v];
        std::array<float, 3> p{}, n{};
        float total = 0;
        for (int i = 0; i < 4; ++i) {
            const float w = vertex.weights[i];
            if (w <= 0) continue;
            const auto& s = skin[vertex.bones[i]];
            const auto sp = s.Point(vertex.position), sn = s.Vector(vertex.normal);
            for (int c = 0; c < 3; ++c) { p[c] += w * sp[c]; n[c] += w * sn[c]; }
            total += w;
        }
        if (total <= 0) { p = vertex.position; n = vertex.normal; }
        const float length = std::sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);
        if (length > 1e-8f) for (auto& c : n) c /= length;
        memcpy(&positions[v * 3], p.data(), sizeof(p));
        memcpy(&normals[v * 3], n.data(), sizeof(n));
    }
}
}
